--- palette.rs ---
     1	//! Command palette — the deep-menu registry (⌘K UI, typed Command registry
     2	//! with scope + availability predicates). One registry drives the palette,
     3	//! the native menubar, and the header overflow.
     4	//! Owned by the Palette workstream (feat/desktop-palette); real commands are
     5	//! wired at integration time (app.rs), not here.
     6	
     7	use leptos::ev::{self, KeyboardEvent};
     8	use leptos::prelude::*;
     9	
    10	use crate::search::fuzzy_score;
    11	
    12	// ── Types ──────────────────────────────────────────────────────────────────
    13	
    14	/// The scope a command belongs to — used for grouping and as a visible tag
    15	/// in palette rows.
    16	#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
    17	pub enum CommandScope {
    18	    Session,
    19	    Files,
    20	    Repo,
    21	    Browser,
    22	    App,
    23	}
    24	
    25	impl CommandScope {
    26	    /// Human-readable label for the scope group header in the palette.
    27	    fn label(self) -> &'static str {
    28	        match self {
    29	            CommandScope::Session => "Session",
    30	            CommandScope::Files => "Files",
    31	            CommandScope::Repo => "Repo",
    32	            CommandScope::Browser => "Browser",
    33	            CommandScope::App => "App",
    34	        }
    35	    }
    36	
    37	    /// Stable sort order for scope groups in the palette.
    38	    fn order(self) -> usize {
    39	        match self {
    40	            CommandScope::Session => 0,
    41	            CommandScope::Files => 1,
    42	            CommandScope::Repo => 2,
    43	            CommandScope::Browser => 3,
    44	            CommandScope::App => 4,
    45	        }
    46	    }
    47	}
    48	
    49	/// A single command in the deep-menu registry. One `Command` added to the
    50	/// registry appears in the ⌘K palette, the native menubar, *and* the header
    51	/// overflow — the integrator registers it once.
    52	#[derive(Clone)]
    53	pub struct Command {
    54	    /// Stable identifier (e.g. `"new-session"`). Used for deduplication
    55	    /// and event routing.
    56	    pub id: &'static str,
    57	    /// Display title shown in the palette row.
    58	    pub title: String,
    59	    /// Optional subtitle / supplementary text (e.g. a keyboard shortcut hint).
    60	    pub hint: Option<String>,
    61	    /// Scope for grouping and visual tagging.
    62	    pub scope: CommandScope,
    63	    /// Optional composer `/` alias (e.g. `Some("/new")`). Commands without
    64	    /// an alias are invisible to the slash popover; the ⌘K palette still
    65	    /// lists them. The alias is display + match text for `slash_filter`.
    66	    pub slash: Option<&'static str>,
    67	    /// Availability predicate evaluated at open/filter time. Host-gating
    68	    /// (e.g. Tauri-only commands) happens here: the integrator wires a
    69	    /// `Signal<bool>` that reflects the current host.
    70	    pub enabled: Signal<bool>,
    71	    /// Action to run when the command is selected and Enter is pressed
    72	    /// (or the row is clicked).
    73	    pub run: Callback<()>,
    74	}
    75	
    76	/// A cloneable, signal-backed command registry. Create one with
    77	/// [`CommandRegistry::new`], register commands via [`register`](CommandRegistry::register),
    78	/// and pass it to [`PaletteView`]. Registration after mount works — the
    79	/// palette reacts when commands are added later.
    80	///
    81	/// # Example (integrator's app.rs)
    82	///
    83	/// ```ignore
    84	/// let registry = CommandRegistry::new();
    85	/// registry.register(Command {
    86	///     id: "toggle-deck",
    87	///     title: "Toggle Context Deck".into(),
    88	///     hint: None,
    89	///     scope: CommandScope::App,
    90	///     slash: None,
    91	///     enabled: Signal::derive(move || show_deck.get()),
    92	///     run: Callback::new(move |_| show_deck.update(|v| *v = !*v)),
    93	/// });
    94	///
    95	/// view! { <PaletteView registry=registry /> }
    96	/// ```
    97	#[derive(Clone)]
    98	pub struct CommandRegistry {
    99	    commands: RwSignal<Vec<Command>>,
   100	}
   101	
   102	impl CommandRegistry {
   103	    /// Create an empty command registry, ready for registration.
   104	    pub fn new() -> Self {
   105	        Self {
   106	            commands: RwSignal::new(Vec::new()),
   107	        }
   108	    }
   109	
   110	    /// Register a command. Safe to call from any reactive scope; the palette
   111	    /// picks up new commands on the next open or filter cycle.
   112	    pub fn register(&self, cmd: Command) {
   113	        self.commands.update(|cmds| cmds.push(cmd));
   114	    }
   115	
   116	    /// Run the enabled command identified by `id`. Returns `true` when a
   117	    /// matching, currently-enabled command was found and its callback fired;
   118	    /// `false` when the id is unknown or the command is registered but gated
   119	    /// off by its `enabled` signal (a disabled command is refused, never run).
   120	    ///
   121	    /// This is the dispatch entry point event-driven callers share with the
   122	    /// ⌘K palette: the native menubar emits a `menu-command` event carrying a
   123	    /// command id, the host bridge hands the id here, and the registry routes
   124	    /// it to the same `Callback` the palette runs. Unknown ids (a stray menu
   125	    /// id that is not a palette command) resolve to a no-op `false`.
   126	    pub fn run(&self, id: &str) -> bool {
   127	        let Some(cmd) = self
   128	            .commands
   129	            .get_untracked()
   130	            .into_iter()
   131	            .find(|c| c.id == id)
   132	        else {
   133	            return false;
   134	        };
   135	        if cmd.enabled.get_untracked() {
   136	            cmd.run.run(());
   137	            true
   138	        } else {
   139	            false
   140	        }
   141	    }
   142	
   143	    /// Filter commands that carry a slash alias by a subsequence match of
   144	    /// `query` against the alias (leading `/` on either side ignored). An
   145	    /// empty query returns every command with a slash alias in registry
   146	    /// order. Drives the composer `/` popover.
   147	    pub fn slash_filter(&self, query: &str) -> Vec<Command> {
   148	        let q = query.trim().trim_start_matches('/').to_lowercase();
   149	        self.commands
   150	            .get_untracked()
   151	            .into_iter()
   152	            .filter(|cmd| {
   153	                let Some(alias) = cmd.slash else {
   154	                    return false;
   155	                };
   156	                let target = alias.trim_start_matches('/');
   157	                if q.is_empty() {
   158	                    return true;
   159	                }
   160	                slash_subseq(target, &q)
   161	            })
   162	            .collect()
   163	    }
   164	}
