   172	// ── Fuzzy matching ─────────────────────────────────────────────────────────
   173	
   174	/// Subsequence match for slash aliases. Case-insensitive; returns true when
   175	/// every char of `query` appears in order inside `target`. Mirrors the shape
   176	/// of ocean-tui's `shell::slash::subseq_score` (a boolean gate — scoring is
   177	/// unnecessary for the short alias set).
   178	fn slash_subseq(target: &str, query: &str) -> bool {
   179	    let target = target.to_lowercase();
   180	    let mut ti = target.chars().peekable();
   181	    for qc in query.chars() {
   182	        loop {
   183	            match ti.next() {
   184	                Some(tc) if tc == qc => break,
   185	                Some(_) => continue,
   186	                None => return false,
   187	            }
   188	        }
   189	    }
   190	    true
   191	}
