    28	
    29	/// The workspace root for a session: its own `workspace_root` if present,
    30	/// otherwise the reported `cwd` (which the daemon fills from the stored root).
    31	pub(crate) fn session_root(s: &SessionSummary) -> &str {
    32	    s.workspace_root
    33	        .as_deref()
    34	        .filter(|r| !r.is_empty())
    35	        .unwrap_or(s.cwd.as_str())
    36	}
    37	
    38	/// Resolve the catalogue project that owns `root` when the daemon didn't
    39	/// attach `owning_project` (worktree/subdir sessions, older daemons): exact
    40	/// `workspace_root` match first, then component-boundary prefix against each
    41	/// project's `workspace_root` and registered worktree paths. The LONGEST
    42	/// matching root wins so nested project roots never steal each other's
    43	/// sessions. Pure — unit-testable without WASM.
    44	pub(crate) fn project_for_root<'a>(
    45	    projects: &'a [ProjectInfo],
    46	    root: &str,
    47	) -> Option<&'a ProjectInfo> {
    48	    if root.is_empty() {
    49	        return None;
    50	    }
    51	    if let Some(p) = projects
    52	        .iter()
    53	        .find(|p| !p.workspace_root.is_empty() && p.workspace_root == root)
    54	    {
    55	        return Some(p);
    56	    }
    57	    projects
    58	        .iter()
    59	        .filter_map(|p| {
    60	            let roots = std::iter::once(p.workspace_root.as_str())
    61	                .chain(p.worktrees.iter().map(|wt| wt.path.as_str()));
    62	            roots
    63	                .filter(|r| !r.is_empty() && is_path_prefix(r, root))
    64	                .map(str::len)
    65	                .max()
    66	                .map(|len| (len, p))
    67	        })
    68	        .max_by_key(|(len, _)| *len)
    69	        .map(|(_, p)| p)
    70	}
