    94	fn project_root_from_parent(parent: &str, name: &str) -> String {
    95	    let parent = parent.trim();
    96	    let base = parent.trim_end_matches('/');
    97	    let slug = project_slug(name);
    98	    if base.is_empty() {
    99	        if parent.starts_with('/') {
   100	            format!("/{slug}")
   101	        } else {
   102	            slug
   103	        }
   104	    } else {
   105	        format!("{base}/{slug}")
   106	    }
   107	}
