   150	/// Group sessions for the panel display: project-first, newest sessions
   151	/// first, "Other" last. Every daemon-catalogued session is retained so the
   152	/// desktop panel stays in parity with the TUI's persisted-session discovery.
   153	/// Pure — no WASM, testable with `cargo test`.
   154	pub(crate) fn group_for_panel(
   155	    sessions: &[SessionSummary],
   156	    projects: &[ProjectInfo],
   157	    _active_id: Option<&str>,
   158	) -> Vec<ProjectSection> {
   159	    // The TUI includes persisted zero-turn drafts. Do not silently hide them
   160	    // here: a session returned by the daemon belongs in the desktop catalogue.
   161	
   162	    // Collect into sections by project membership.
   163	    let mut sections: Vec<ProjectSection> = Vec::new();
   164	    for s in sessions {
   165	        let (key, label, is_proj) = if let Some(op) = &s.owning_project {
   166	            let label = if op.name.trim().is_empty() {
   167	                op.id.clone()
   168	            } else {
   169	                op.name.clone()
   170	            };
   171	            (op.id.clone(), label, true)
   172	        } else if let Some(p) = project_for_root(projects, session_root(s)) {
   173	            let label = if p.name.trim().is_empty() {
   174	                p.workspace_root.clone()
   175	            } else {
   176	                p.name.clone()
   177	            };
   178	            (p.id.clone(), label, true)
   179	        } else {
   180	            ("__other__".to_string(), "Other".to_string(), false)
   181	        };
   182	
   183	        match sections
   184	            .iter_mut()
   185	            .find(|sec: &&mut ProjectSection| sec.key == key)
   186	        {
   187	            Some(sec) => sec.sessions.push(s.clone()),
   188	            None => {
   189	                let is_git = if is_proj {
   190	                    projects
   191	                        .iter()
   192	                        .find(|p| p.id == key)
   193	                        .is_some_and(|p| p.git_branch.is_some() || p.git_dirty.is_some())
   194	                } else {
   195	                    false
   196	                };
   197	                sections.push(ProjectSection {
   198	                    key,
   199	                    label,
   200	                    is_project: is_proj,
   201	                    is_git,
   202	                    sessions: vec![s.clone()],
   203	                    worktrees: None,
   204	                    main_group: None,
   205	                })
   206	            }
   207	        }
   208	    }
   209	
   210	    // Zero-session projects still render as empty groups so a freshly-created
   211	    // project (no sessions yet) appears in the panel. Append a section for any
   212	    // project that didn't collect a session above, keyed by the project id so
   213	    // later sessions merge into it.
   214	    for p in projects {
   215	        if sections.iter().any(|sec| sec.key == p.id) {
   216	            continue;
   217	        }
   218	        let label = if p.name.trim().is_empty() {
   219	            p.workspace_root
   220	                .rsplit('/')
   221	                .find(|s| !s.is_empty())
   222	                .map(str::to_string)
   223	                .unwrap_or_else(|| p.workspace_root.clone())
   224	        } else {
   225	            p.name.clone()
   226	        };
   227	        sections.push(ProjectSection {
   228	            key: p.id.clone(),
   229	            label,
   230	            is_project: true,
   231	            is_git: p.git_branch.is_some() || p.git_dirty.is_some(),
   232	            sessions: Vec::new(),
   233	            worktrees: None,
   234	            main_group: None,
   235	        });
   236	    }
   237	
   238	    // Sort sessions inside each group: newest first (ISO-8601 lexicographic cmp).
   239	    for sec in &mut sections {
   240	        sec.sessions.sort_by(|a, b| b.updated_at.cmp(&a.updated_at));
   241	    }
   242	    // Worktree + main-group bucketing: second pass inside each project section.
   243	    // Sessions whose workspace root sits under a project worktree's path
   244	    // (component-boundary prefix match) group under that sub-row — worktree
   245	    // match always wins first so sessions never double-bucket. After matching,
   246	    // unmatched sessions matching the project's workspace_root form the main
   247	    // group; the rest remain flat strays. Zero worktrees → today's flat
   248	    // rendering (no sub-groups, no main node).
   249	    for sec in &mut sections {
   250	        if !sec.is_project {
   251	            continue;
   252	        }
   253	        let proj = projects.iter().find(|p| p.id == sec.key);
   254	        let has_wts = proj.is_some_and(|p| !p.worktrees.is_empty());
   255	        if !has_wts {
   256	            continue;
   257	        }
   258	        let proj = proj.unwrap(); // safe: has_wts ensures Some
   259	        let wts = &proj.worktrees;
   260	        // Materialize every registered worktree up front. Empty worktrees are
   261	        // still real project context and must remain visible in the drawer.
   262	        let mut wt_groups: Vec<WorktreeGroup> = wts
   263	            .iter()
   264	            .map(|wt| WorktreeGroup {
   265	                root: wt.path.clone(),
   266	                branch: wt.branch.clone(),
   267	                sessions: Vec::new(),
   268	            })
   269	            .collect();
   270	        let mut unmatched: Vec<SessionSummary> = Vec::new();
   271	        for s in &sec.sessions {
   272	            let root = session_root(s);
   273	            let matching = wts.iter().find(|wt| is_path_prefix(&wt.path, root));
   274	            if let Some(wt) = matching {
   275	                // Every registered worktree was seeded above, so a match always
   276	                // resolves to an existing group.
   277	                if let Some(group) = wt_groups.iter_mut().find(|g| g.root == wt.path) {
   278	                    group.sessions.push(s.clone());
   279	                }
   280	            } else {
   281	                unmatched.push(s.clone());
   282	            }
   283	        }
   284	        // Carve main group from unmatched leftovers: sessions whose root lives
   285	        // under the project's workspace_root form the main node; the rest are
   286	        // true strays. Only applies when the project has registered worktrees.
   287	        let workspace_root = proj.workspace_root.as_str();
   288	        let mut main_sessions: Vec<SessionSummary> = Vec::new();
   289	        let mut strays: Vec<SessionSummary> = Vec::new();
   290	        for s in &unmatched {
   291	            if is_path_prefix(workspace_root, session_root(s)) {
   292	                main_sessions.push(s.clone());
   293	            } else {
   294	                strays.push(s.clone());
   295	            }
   296	        }
   297	        if !wt_groups.is_empty() {
   298	            for wt in &mut wt_groups {
   299	                wt.sessions.sort_by(|a, b| b.updated_at.cmp(&a.updated_at));
   300	            }
   301	            wt_groups.sort_by(|a, b| {
   302	                let a_has = a.branch.is_some();
   303	                let b_has = b.branch.is_some();
   304	                match (a_has, b_has) {
   305	                    (true, false) => std::cmp::Ordering::Less,
   306	                    (false, true) => std::cmp::Ordering::Greater,
   307	                    _ => b
   308	                        .sessions
   309	                        .first()
   310	                        .map(|s| s.updated_at.as_str())
   311	                        .unwrap_or("")
   312	                        .cmp(
   313	                            a.sessions
   314	                                .first()
   315	                                .map(|s| s.updated_at.as_str())
   316	                                .unwrap_or(""),
   317	                        ),
   318	                }
   319	            });
   320	            sec.worktrees = Some(wt_groups);
   321	        }
   322	        if !main_sessions.is_empty() {
   323	            main_sessions.sort_by(|a, b| b.updated_at.cmp(&a.updated_at));
