--- palette.rs ---
     1	//! Command palette — the deep-menu registry (⌘K UI, typed Command registry
     2	//! with scope + availability predicates). One registry drives the palette,
     3	//! the native menubar, and the header overflow.
     4	//! Owned by the Palette workstream (feat/desktop-palette); real commands are
     5	//! wired at integration time (app.rs), not here.
     6	
     7	use leptos::ev::{self, KeyboardEvent};
     8	use leptos::prelude::*;
     9	
    10	use crate::search::fuzzy_score;
    11	
    12	// ── Types ──────────────────────────────────────────────────────────────────
    13	
    14	/// The scope a command belongs to — used for grouping and as a visible tag
    15	/// in palette rows.
    16	#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
    17	pub enum CommandScope {
    18	    Session,
    19	    Files,
    20	    Repo,
    21	    Browser,
    22	    App,
    23	}
    24	
    25	impl CommandScope {
    26	    /// Human-readable label for the scope group header in the palette.
    27	    fn label(self) -> &'static str {
    28	        match self {
    29	            CommandScope::Session => "Session",
    30	            CommandScope::Files => "Files",
    31	            CommandScope::Repo => "Repo",
    32	            CommandScope::Browser => "Browser",
    33	            CommandScope::App => "App",
    34	        }
    35	    }
    36	
    37	    /// Stable sort order for scope groups in the palette.
    38	    fn order(self) -> usize {
    39	        match self {
    40	            CommandScope::Session => 0,
    41	            CommandScope::Files => 1,
    42	            CommandScope::Repo => 2,
    43	            CommandScope::Browser => 3,
    44	            CommandScope::App => 4,
    45	        }
    46	    }
    47	}
    48	
    49	/// A single command in the deep-menu registry. One `Command` added to the
    50	/// registry appears in the ⌘K palette, the native menubar, *and* the header
    51	/// overflow — the integrator registers it once.
    52	#[derive(Clone)]
    53	pub struct Command {
    54	    /// Stable identifier (e.g. `"new-session"`). Used for deduplication
    55	    /// and event routing.
    56	    pub id: &'static str,
    57	    /// Display title shown in the palette row.
    58	    pub title: String,
    59	    /// Optional subtitle / supplementary text (e.g. a keyboard shortcut hint).
    60	    pub hint: Option<String>,
    61	    /// Scope for grouping and visual tagging.
    62	    pub scope: CommandScope,
    63	    /// Optional composer `/` alias (e.g. `Some("/new")`). Commands without
    64	    /// an alias are invisible to the slash popover; the ⌘K palette still
    65	    /// lists them. The alias is display + match text for `slash_filter`.
    66	    pub slash: Option<&'static str>,
    67	    /// Availability predicate evaluated at open/filter time. Host-gating
    68	    /// (e.g. Tauri-only commands) happens here: the integrator wires a
    69	    /// `Signal<bool>` that reflects the current host.
    70	    pub enabled: Signal<bool>,
    71	    /// Action to run when the command is selected and Enter is pressed
    72	    /// (or the row is clicked).
    73	    pub run: Callback<()>,
    74	}
    75	
    76	/// A cloneable, signal-backed command registry. Create one with
    77	/// [`CommandRegistry::new`], register commands via [`register`](CommandRegistry::register),
    78	/// and pass it to [`PaletteView`]. Registration after mount works — the
    79	/// palette reacts when commands are added later.
    80	///
    81	/// # Example (integrator's app.rs)
    82	///
    83	/// ```ignore
    84	/// let registry = CommandRegistry::new();
    85	/// registry.register(Command {
    86	///     id: "toggle-deck",
    87	///     title: "Toggle Context Deck".into(),
    88	///     hint: None,
    89	///     scope: CommandScope::App,
    90	///     slash: None,
    91	///     enabled: Signal::derive(move || show_deck.get()),
    92	///     run: Callback::new(move |_| show_deck.update(|v| *v = !*v)),
    93	/// });
    94	///
    95	/// view! { <PaletteView registry=registry /> }
    96	/// ```
    97	#[derive(Clone)]
    98	pub struct CommandRegistry {
    99	    commands: RwSignal<Vec<Command>>,
   100	}
   101	
   102	impl CommandRegistry {
   103	    /// Create an empty command registry, ready for registration.
   104	    pub fn new() -> Self {
   105	        Self {
   106	            commands: RwSignal::new(Vec::new()),
   107	        }
   108	    }
   109	
   110	    /// Register a command. Safe to call from any reactive scope; the palette
   111	    /// picks up new commands on the next open or filter cycle.
   112	    pub fn register(&self, cmd: Command) {
   113	        self.commands.update(|cmds| cmds.push(cmd));
   114	    }
   115	
   116	    /// Run the enabled command identified by `id`. Returns `true` when a
   117	    /// matching, currently-enabled command was found and its callback fired;
   118	    /// `false` when the id is unknown or the command is registered but gated
   119	    /// off by its `enabled` signal (a disabled command is refused, never run).
   120	    ///
   121	    /// This is the dispatch entry point event-driven callers share with the
   122	    /// ⌘K palette: the native menubar emits a `menu-command` event carrying a
   123	    /// command id, the host bridge hands the id here, and the registry routes
   124	    /// it to the same `Callback` the palette runs. Unknown ids (a stray menu
   125	    /// id that is not a palette command) resolve to a no-op `false`.
   126	    pub fn run(&self, id: &str) -> bool {
   127	        let Some(cmd) = self
   128	            .commands
   129	            .get_untracked()
   130	            .into_iter()
   131	            .find(|c| c.id == id)
   132	        else {
   133	            return false;
   134	        };
   135	        if cmd.enabled.get_untracked() {
   136	            cmd.run.run(());
   137	            true
   138	        } else {
   139	            false
   140	        }
   141	    }
   142	
   143	    /// Filter commands that carry a slash alias by a subsequence match of
   144	    /// `query` against the alias (leading `/` on either side ignored). An
   145	    /// empty query returns every command with a slash alias in registry
   146	    /// order. Drives the composer `/` popover.
   147	    pub fn slash_filter(&self, query: &str) -> Vec<Command> {
   148	        let q = query.trim().trim_start_matches('/').to_lowercase();
   149	        self.commands
   150	            .get_untracked()
   151	            .into_iter()
   152	            .filter(|cmd| {
   153	                let Some(alias) = cmd.slash else {
   154	                    return false;
   155	                };
   156	                let target = alias.trim_start_matches('/');
   157	                if q.is_empty() {
   158	                    return true;
   159	                }
   160	                slash_subseq(target, &q)
   161	            })
   162	            .collect()
   163	    }
   164	}
   165	
   166	impl Default for CommandRegistry {
   167	    fn default() -> Self {
   168	        Self::new()
   169	    }
   170	}
   171	
   172	// ── Fuzzy matching ─────────────────────────────────────────────────────────
   173	
   174	/// Subsequence match for slash aliases. Case-insensitive; returns true when
   175	/// every char of `query` appears in order inside `target`. Mirrors the shape
   176	/// of ocean-tui's `shell::slash::subseq_score` (a boolean gate — scoring is
   177	/// unnecessary for the short alias set).
   178	fn slash_subseq(target: &str, query: &str) -> bool {
   179	    let target = target.to_lowercase();
   180	    let mut ti = target.chars().peekable();
   181	    for qc in query.chars() {
   182	        loop {
   183	            match ti.next() {
   184	                Some(tc) if tc == qc => break,
   185	                Some(_) => continue,
   186	                None => return false,
   187	            }
   188	        }
   189	    }
   190	    true
   191	}
   192	
   193	// ── Selection helpers ──────────────────────────────────────────────────────
   194	
   195	/// Wrap-forward: `(idx + 1) % len`. Returns 0 for empty lists.
   196	fn next_index(idx: usize, len: usize) -> usize {
   197	    if len == 0 {
   198	        0
   199	    } else {
   200	        (idx + 1) % len
   201	    }
   202	}
   203	
   204	/// Wrap-backward: `(idx + len - 1) % len`. Returns 0 for empty lists.
   205	fn prev_index(idx: usize, len: usize) -> usize {
   206	    if len == 0 {
   207	        0
   208	    } else {
   209	        (idx + len - 1) % len
   210	    }
   211	}
   212	
   213	// ── Internal working type ──────────────────────────────────────────────────
   214	
   215	#[derive(Clone)]
   216	struct ScoredCommand {
   217	    command: Command,
   218	    score: f64,
   219	}
   220	
   221	impl PartialEq for ScoredCommand {
   222	    fn eq(&self, other: &Self) -> bool {
   223	        self.command.id == other.command.id && self.score == other.score
   224	    }
   225	}
   226	
   227	// ── PaletteView component ──────────────────────────────────────────────────
   228	
   229	/// The ⌘K command palette — a deep-menu overlay that opens on Cmd+K (macOS)
   230	/// or Ctrl+K (everywhere else). Types are grouped by [`CommandScope`];
   231	/// disabled commands are hidden. Fuzzy subsequence matching with scoring
   232	/// keeps the most relevant commands at the top of each group.
   233	///
   234	/// # Keyboard
   235	///
   236	/// | Key          | Action                                      |
   237	/// |-------------|---------------------------------------------|
   238	/// | ⌘K / Ctrl+K | Open palette, focus input, reset query      |
   239	/// | Esc          | Close palette                               |
   240	/// | ↑ / ↓        | Move selection (wraps)                       |
   241	/// | Enter        | Run selected command, close palette          |
   242	/// | Backdrop     | click closes palette                         |
   243	#[component]
   244	pub fn PaletteView(registry: CommandRegistry, open: RwSignal<bool>) -> impl IntoView {
   245	    let query = RwSignal::new(String::new());
   246	    let selected_index = RwSignal::new(0usize);
   247	    let input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
   248	
   249	    // ── Window-level keydown: Cmd+K / Ctrl+K opens the palette ──────────
   250	    let _key_listener = window_event_listener(ev::keydown, move |e: KeyboardEvent| {
   251	        // metaKey on macOS, ctrlKey elsewhere. We check both so Cmd+K works
   252	        // on Mac and Ctrl+K works everywhere else.
   253	        if !e.is_composing()
   254	            && (e.meta_key() || e.ctrl_key())
   255	            && !e.shift_key()
   256	            && !e.alt_key()
   257	            && e.key().eq_ignore_ascii_case("k")
   258	        {
   259	            e.prevent_default();
   260	            query.set(String::new());
   261	            selected_index.set(0);
   262	            open.set(true);
   263	        }
   264	    });
   265	    on_cleanup(move || _key_listener.remove());
   266	
   267	    // ── Auto-focus the input when the palette opens ──────────────────────
   268	    Effect::new(move |_| {
   269	        if open.get() {
   270	            request_animation_frame(move || {
   271	                if let Some(el) = input_ref.get() {
   272	                    let _ = el.focus();
   273	                    el.select();
   274	                }
   275	            });
   276	        }
   277	    });
   278	
   279	    // ── Filter + group + score ───────────────────────────────────────────
   280	    // Re-derived every time `query` or `registry.commands` changes.
   281	    let filtered_groups: Memo<Vec<(CommandScope, Vec<ScoredCommand>)>> = Memo::new(move |_| {
   282	        let q = query.get();
   283	        let q = q.trim();
   284	        let cmds = registry.commands.get();
   285	
   286	        let mut groups: Vec<(CommandScope, Vec<ScoredCommand>)> = Vec::new();
   287	
   288	        for cmd in cmds.iter() {
   289	            // Host/state gating: disabled commands are invisible.
   290	            if !cmd.enabled.get() {
   291	                continue;
   292	            }
   293	
   294	            let score = if q.is_empty() {
   295	                0.0
   296	            } else {
   297	                match fuzzy_score(q, &cmd.title) {
   298	                    Some(s) => s,
   299	                    None => continue, // no match → hidden
   300	                }
   301	            };
   302	
   303	            let group = groups.iter_mut().find(|(s, _)| *s == cmd.scope);
   304	            if let Some((_, cmds)) = group {
   305	                cmds.push(ScoredCommand {
   306	                    command: cmd.clone(),
   307	                    score,
   308	                });
   309	            } else {
   310	                groups.push((
   311	                    cmd.scope,
   312	                    vec![ScoredCommand {
   313	                        command: cmd.clone(),
   314	                        score,
   315	                    }],
   316	                ));
   317	            }
   318	        }
   319	
   320	        // Sort within each group by score descending (best first).
   321	        for (_, cmds) in groups.iter_mut() {
