    72	fn project_slug(name: &str) -> String {
    73	    let mut slug = String::new();
    74	    let mut just_dashed = false;
    75	    for ch in name.trim().chars() {
    76	        if ch.is_ascii_alphanumeric() {
    77	            slug.push(ch.to_ascii_lowercase());
    78	            just_dashed = false;
    79	        } else if !slug.is_empty() && !just_dashed {
    80	            slug.push('-');
    81	            just_dashed = true;
    82	        }
    83	    }
    84	    while slug.ends_with('-') {
    85	        slug.pop();
    86	    }
    87	    if slug.is_empty() {
    88	        "project-name".to_string()
    89	    } else {
    90	        slug
    91	    }
    92	}
