   109	/// Derive a project name from a directory path: the last non-empty
   110	/// segment after stripping a trailing slash. Falls back to "project"
   111	/// when the path is blank or every segment is empty.
   112	fn derive_project_name(path: &str) -> String {
   113	    path.trim()
   114	        .trim_end_matches('/')
   115	        .rsplit('/')
   116	        .find(|s| !s.is_empty())
   117	        .unwrap_or("project")
   118	        .to_string()
   119	}
