   250	/// arrival order so replayed commands run in the order the user clicked them.
   251	///
   252	/// Race safety: both the `event.listen` IPC (registering the subscriber) and
   253	/// this command travel the webview's single FIFO IPC channel, and `listen` is
   254	/// dispatched first (see app.rs), so the subscriber is registered before the
   255	/// drain emits — no replayed event is lost.
   256	#[tauri::command]
   257	fn ui_ready(app: AppHandle, state: State<'_, AppState>) -> Result<(), String> {
   258	    let pending = {
   259	        let mut bridge = state.menu.lock();
   260	        bridge.ready = true;
   261	        std::mem::take(&mut bridge.pending)
   262	    };
   263	    for id in pending {
   264	        let _ = app.emit("menu-command", id);
   265	    }
   266	    Ok(())
   267	}
